<?php
$pageTitle = 'Admin Dashboard';
require_once __DIR__ . '/../includes/admin_init.php';
$metrics = $pdo->query("SELECT COUNT(*) AS total, SUM(CASE WHEN status IN ('calculated','saved','draft','submitted','under_review') THEN 1 ELSE 0 END) AS pending, COALESCE(SUM(zakat_due),0) AS assessed FROM zakat_calculations")->fetch(PDO::FETCH_ASSOC);
$payments = $pdo->query("SELECT COUNT(*) AS total, SUM(CASE WHEN status IN ('pending','under_review','processing','initiated') THEN 1 ELSE 0 END) AS pending, COALESCE(SUM(CASE WHEN status IN ('confirmed','approved') THEN amount ELSE 0 END),0) AS verified FROM zakat_payments")->fetch(PDO::FETCH_ASSOC);
$users = (int)$pdo->query("SELECT COUNT(*) FROM users WHERE role_id=2")->fetchColumn();
$recent = $pdo->query("SELECT c.id,c.reference_no,c.zakat_due,c.status,c.nisab_basis,u.full_name FROM zakat_calculations c LEFT JOIN users u ON u.id=c.user_id ORDER BY c.created_at DESC LIMIT 10")->fetchAll(PDO::FETCH_ASSOC);
require_once __DIR__ . '/../includes/admin_header.php';
$cards=[['Donors',$users,'fa-users'],['Calculations',(int)$metrics['total'],'fa-calculator'],['Awaiting Review',(int)$metrics['pending'],'fa-clock'],['Payment Requests',(int)$payments['total'],'fa-receipt'],['Pending Payments',(int)$payments['pending'],'fa-hourglass-half'],['Verified Cash',money($payments['verified']),'fa-money-bill-wave']];
?>
<div class="mb-6"><h1 class="text-2xl font-bold">Zakat Operations Overview</h1><p class="text-slate-500 text-sm">Calculation, payment and collection are different stages. Physical goods are not counted as cash.</p></div>
<div class="grid sm:grid-cols-2 xl:grid-cols-3 gap-4"><?php foreach($cards as $card): ?><div class="rounded-2xl border bg-white p-5 shadow-sm"><div class="flex items-center justify-between"><p class="text-slate-500 text-sm"><?=e($card[0])?></p><i class="fa-solid <?=e($card[2])?> text-emerald-700"></i></div><p class="text-2xl font-bold mt-2"><?=e((string)$card[1])?></p></div><?php endforeach; ?></div>
<div class="bg-white border rounded-2xl mt-6 overflow-hidden"><div class="p-5 flex justify-between items-center"><h2 class="font-bold text-lg">Recent Calculations</h2><a href="calculations/index.php" class="text-emerald-700 text-sm">Manage calculations →</a></div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="text-left p-3">Reference</th><th class="text-left p-3">Donor</th><th class="text-left p-3">Basis</th><th class="text-right p-3">Calculated Due</th><th class="text-left p-3">Status</th><th class="p-3">Action</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr class="border-t"><td class="p-3"><?=e($r['reference_no'])?></td><td class="p-3"><?=e($r['full_name']??'Unknown')?></td><td class="p-3"><?=e(ucfirst($r['nisab_basis']))?></td><td class="p-3 text-right"><?=e(money($r['zakat_due']))?></td><td class="p-3"><?=e(ucwords(str_replace('_',' ',$r['status'])))?></td><td class="p-3 text-center"><a class="text-emerald-700" href="calculations/index.php?search=<?=urlencode($r['reference_no'])?>">Review</a></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="mt-5 flex gap-3"><a href="payments/index.php" class="rounded-xl bg-emerald-700 px-4 py-3 text-white">Review payments</a><a href="calculations/index.php" class="rounded-xl border px-4 py-3">View calculations</a></div>
<?php require_once __DIR__ . '/../includes/admin_footer.php'; ?>
